import { scope } from "arktype"

// Define the schema using the scope API with generic Page<T>
export const types = scope({
    User: {
        id: "string.uuid",
        name: "1 <= string <= 50"
    },
    Post: {
        id: "string.uuid",
        title: "1 <= string <= 120",
        authorId: "string.uuid"
    },
    "Page<T>": {
        items: "T[]",
        total: "number.integer >= 0",
        page: "number.integer >= 1",
        perPage: "1 <= number.integer <= 100",
        hasNext: "boolean"
    },
    UserPage: "Page<User>",
    PostPage: "Page<Post>"
}).export()

// Extract TypeScript types from the scope exports
export type User = typeof types.User.infer
export type Post = typeof types.Post.infer
export type UserPage = typeof types.UserPage.infer
export type PostPage = typeof types.PostPage.infer

/**
 * Validates a paginated response for the specified resource kind.
 * Returns the validated page object or throws via ArkType's assertion API.
 */
export function validatePage(kind: "User", page: unknown): UserPage
export function validatePage(kind: "Post", page: unknown): PostPage
export function validatePage(kind: "User" | "Post", page: unknown): UserPage | PostPage
export function validatePage(kind: "User" | "Post", page: unknown) {
    if (kind === "User") {
        return types.UserPage.assert(page)
    } else if (kind === "Post") {
        return types.PostPage.assert(page)
    } else {
        throw new Error(`Unknown kind: ${kind}`)
    }
}

import * as fs from "node:fs"
import { validatePage } from "./src/validator.js"

function main() {
    let inputStr = ""
    try {
        inputStr = fs.readFileSync(0, "utf-8")
    } catch (e: any) {
        console.log(`INVALID: Failed to read stdin: ${e.message}`)
        process.exit(0)
    }

    let payload: any
    try {
        payload = JSON.parse(inputStr)
    } catch (e: any) {
        console.log(`INVALID: Invalid JSON input: ${e.message}`)
        process.exit(0)
    }

    if (typeof payload !== "object" || payload === null) {
        console.log("INVALID: Input is not a JSON object")
        process.exit(0)
    }

    const { kind, page } = payload

    if (kind !== "User" && kind !== "Post") {
        console.log(`INVALID: Unknown kind: ${kind}`)
        process.exit(0)
    }

    try {
        const validated = validatePage(kind, page)
        console.log("VALID")
        console.log(JSON.stringify(validated))
    } catch (e: any) {
        // e.message contains the validation errors
        // Print exactly one line starting with "INVALID: " followed by a space and an error description.
        // Replace any newlines in e.message with spaces to ensure it is exactly one line.
        const msg = e.message.replace(/\s+/g, " ").trim()
        console.log(`INVALID: ${msg}`)
    }
}

main()

import { execSync } from "node:child_process"

const testCases = [
    {
        name: "1. Well-formed Page<User>",
        input: {
            kind: "User",
            page: {
                items: [
                    { id: "e6f85108-9dfd-4a15-b0b3-f0928a3a9bf0", name: "Alice" },
                    { id: "bc385208-8dfd-4a15-b0b3-f0928a3a9bf1", name: "Bob" }
                ],
                total: 2,
                page: 1,
                perPage: 10,
                hasNext: false
            }
        },
        expectedStatus: "VALID",
        expectedCheck: (output: string) => {
            const lines = output.trim().split("\n")
            if (lines[0] !== "VALID") return false
            const parsed = JSON.parse(lines[1])
            return parsed.items.length === 2 && parsed.items[0].name === "Alice"
        }
    },
    {
        name: "2. Well-formed Page<Post>",
        input: {
            kind: "Post",
            page: {
                items: [
                    { id: "e6f85108-9dfd-4a15-b0b3-f0928a3a9bf0", title: "Post 1", authorId: "bc385208-8dfd-4a15-b0b3-f0928a3a9bf1" }
                ],
                total: 1,
                page: 1,
                perPage: 10,
                hasNext: false
            }
        },
        expectedStatus: "VALID",
        expectedCheck: (output: string) => {
            const lines = output.trim().split("\n")
            if (lines[0] !== "VALID") return false
            const parsed = JSON.parse(lines[1])
            return parsed.items.length === 1 && parsed.items[0].title === "Post 1"
        }
    },
    {
        name: "3. Page<User> with malformed items[0] (invalid UUID)",
        input: {
            kind: "User",
            page: {
                items: [
