                total: 1,
                page: 1,
                perPage: 101,
                hasNext: false
            }
        },
        expectedStatus: "INVALID",
        expectedCheck: (output: string) => {
            return output.startsWith("INVALID:") && output.includes("perPage")
        }
    },
    {
        name: "4b. Page<User> perPage outside [1, 100] range (0)",
        input: {
            kind: "User",
            page: {
                items: [
                    { id: "e6f85108-9dfd-4a15-b0b3-f0928a3a9bf0", name: "Alice" }
                ],
                total: 1,
                page: 1,
                perPage: 0,
                hasNext: false
            }
        },
        expectedStatus: "INVALID",
        expectedCheck: (output: string) => {
            return output.startsWith("INVALID:") && output.includes("perPage")
        }
    },
    {
        name: "5. hasNext not a boolean (string 'true')",
        input: {
            kind: "User",
            page: {
                items: [
                    { id: "e6f85108-9dfd-4a15-b0b3-f0928a3a9bf0", name: "Alice" }
                ],
                total: 1,
                page: 1,
                perPage: 10,
                hasNext: "true"
            }
        },
        expectedStatus: "INVALID",
        expectedCheck: (output: string) => {
            return output.startsWith("INVALID:") && output.includes("hasNext")
        }
